export async function api<T>(path: string, options: RequestInit = {}): Promise<T> {
  const token = getAccessToken();
  const res = await fetch(path, {
    ...options,
    credentials: "include",
    headers: {
      ...options.headers,
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
  });

  if (res.status === 401) {
    const refreshed = await refreshSession();
    if (!refreshed) {
      logout();
      throw new Error("Session expired");
    }
    const newToken = getAccessToken();
    const retry = await fetch(path, {
      ...options,
      credentials: "include",
      headers: {
        ...options.headers,
        ...(newToken ? { Authorization: `Bearer ${newToken}` } : {}),
      },
    });
    if (!retry.ok) throw new Error(`Request failed: ${retry.status}`);
    return retry.json() as Promise<T>;
  }

  if (!res.ok) throw new Error(`Request failed: ${res.status}`);
  return res.json() as Promise<T>;
}

async function refreshSession(): Promise<boolean> {
  const res = await fetch("/auth/refresh", {
    method: "POST",
    credentials: "include",
  });
  if (!res.ok) return false;
  const data = (await res.json()) as { accessToken: string };
  setAccessToken(data.accessToken);
  return true;
}

const rotate = async (oldToken: string) => {
  const row = repo.findByHash(sha256(oldToken));
  if (!row || row.expires_at < Date.now() || repo.isFamilyRevoked(row.family_id)) {
    throw new InvalidToken();
  }
  if (row.revoked_at) {
    repo.revokeFamily(row.family_id);
    throw new TokenReuseDetected();
  }
  repo.revoke(row.id);
  const user = await users.findById(row.user_id);
  const access = await signAccessToken(user, row.family_id);
  const refresh = newRefreshToken();
  repo.insert({
    familyId: row.family_id,
    userId: user.id,
    hash: sha256(refresh),
    expiresAt: Date.now() + REFRESH_TOKEN_TTL_DAYS * 24 * 60 * 60 * 1000,
  });
  return { access, refresh };
};

const refresh = async (req: Request, res: Response): Promise<void> => {
  const oldToken = (req.cookies as Record<string, string>)["rt"];
  if (!oldToken) {
    res.status(401).json({ error: "No refresh token" });
    return;
  }
  try {
    const { access, refresh: newRefresh } = await tokenService.rotate(oldToken);
    res.cookie("rt", newRefresh, {
      httpOnly: true,
      sameSite: "strict",
      maxAge: REFRESH_TOKEN_TTL_DAYS * 24 * 60 * 60 * 1000,
    });
    res.json({ accessToken: access });
  } catch (err) {
    if (err instanceof InvalidToken || err instanceof TokenReuseDetected) {
      res.clearCookie("rt");
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
    throw err;
  }
};

const revoke = (id: number): void => {
  db.prepare(
    "UPDATE refresh_tokens SET revoked_at = ? WHERE id = ?"
  ).run(Date.now(), id);
};

export function logout(): void {
  _accessToken = null;
  fetch("/auth/logout", { method: "POST", credentials: "include" }).catch(() => {});
  window.location.href = "/login";
}

let _accessToken: string | null = null;

export function getAccessToken(): string | null {
  return _accessToken;
}

export function setAccessToken(token: string): void {
  _accessToken = token;
}

return async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  const auth = req.headers.authorization;
  if (!auth || !auth.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }
  const token = auth.slice(7);
  try {
    const payload = await verifyAccessToken(token);
    const fid = payload["fid"] as string | undefined;
    if (!fid || repo.isFamilyRevoked(fid)) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
    (req as Request & { userId: number }).userId = Number(payload.sub);
    next();
  } catch {
    res.status(401).json({ error: "Unauthorized" });
  }
};

